import { sample, uniqueName, expect, test } from "../../fixtures";

type DocumentOut = { id: string; kind: string; status: string };
type ExtractionOut = { id: string; kind: string; status: string };
type VendorOut = { id: string; status: string };
type AuditTrail = { items: Array<{ action: string }> };

test(
  "rejecting an extraction requires a note and returns the vendor to the member",
  { tag: "@REV-06" },
  async ({ apiAs }) => {
    // Arrange: a member creates a vendor with a unique name and contact email.
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");
    const suffix = uniqueName("REV06").replace(/\s+/g, "-").toLowerCase();

    const createRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("REV-06 Vendor"),
        category: "services",
        contact_email: `rev06-${suffix}@northwind.test`,
      },
    });
    expect(createRes.status()).toBe(201);
    const vendor = (await createRes.json()) as VendorOut;

    // Arrange: upload the three required documents.
    const kinds = ["w9", "insurance_certificate", "contract"] as const;
    for (const kind of kinds) {
      const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind,
          file: {
            name: `${kind}-${suffix}.pdf`,
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4 test document"),
          },
        },
      });
      expect(uploadRes.status()).toBe(201);
    }

    // Arrange: wait until every document has been extracted.
    await expect
      .poll(
        async () => {
          const res = await member.get(`/api/vendors/${vendor.id}/documents`);
          const docs = (await res.json()) as DocumentOut[];
          return docs.length === 3 && docs.every((d) => d.status === "extracted");
        },
        { timeout: 90_000, intervals: [1_000, 2_000, 3_000] },
      )
      .toBe(true);

    // Arrange: submit the vendor so it is in review.
    const submitRes = await member.post(`/api/vendors/${vendor.id}/submit`);
    expect(submitRes.status()).toBe(200);
    expect(((await submitRes.json()) as VendorOut).status).toBe("in_review");

    // Arrange: find the W-9 extraction, which should be pending review.
    const docsRes = await member.get(`/api/vendors/${vendor.id}/documents`);
    const docs = (await docsRes.json()) as DocumentOut[];
    const w9Doc = docs.find((d) => d.kind === "w9");
    expect(w9Doc).toBeDefined();

    const extractionRes = await reviewer.get(`/api/documents/${w9Doc!.id}/extraction`);
    expect(extractionRes.status()).toBe(200);
    const extraction = (await extractionRes.json()) as ExtractionOut;
    expect(extraction.status).toBe("pending_review");
    const extractionId = extraction.id;

    // Act: reject the W-9 extraction without a note.
    const noNoteRes = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
      data: { decision: "reject" },
    });

    // Assert: a rejection without a note is refused.
    expect(noNoteRes.status()).toBe(422);

    // Act: reject the W-9 extraction with a note.
    const rejectRes = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
      data: { decision: "reject", note: "Tax ID does not match" },
    });

    // Assert: the extraction is rejected and the vendor returns to the member.
    expect(rejectRes.status()).toBe(200);
    expect(((await rejectRes.json()) as ExtractionOut).status).toBe("rejected");

    const vendorRes = await member.get(`/api/vendors/${vendor.id}`);
    expect(vendorRes.status()).toBe(200);
    expect(((await vendorRes.json()) as VendorOut).status).toBe("rejected");

    // Assert: the audit trail records the rejection.
    const auditRes = await reviewer.get(`/api/vendors/${vendor.id}/audit`);
    expect(auditRes.status()).toBe(200);
    const audit = (await auditRes.json()) as AuditTrail;
    expect(audit.items.map((e) => e.action)).toContain("extraction.rejected");
  },
);
